insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_87_v1'
from (values
('127.686.d.1.A',3,'A programmer turns the rule ''if the door is open and the alarm is armed, then sound the siren'' into P AND Q → R. This is:','["modeling a real situation with symbolic logic", "drawing a flowchart by hand", "sorting a list", "measuring a circuit"]'::jsonb,0,'Symbolic logic expresses real conditions with symbols and connectives.','original'),
('127.686.d.1.A',4,'Why do computer scientists translate real-world rules into symbolic logic before coding them?','["Symbols run faster on all hardware", "Symbols remove ambiguity so the rule can be tested exactly", "It makes the rule shorter in English", "Logic replaces the need for testing"]'::jsonb,1,'Formal symbols have one precise meaning.','original'),
('127.686.d.1.B',3,'A map of cities joined by roads is best modeled in computer science as a:','["single variable", "stack of plates", "graph with vertices and edges", "sorted array only"]'::jsonb,2,'Cities are vertices and roads are edges.','original'),
('127.686.d.1.B',4,'A company org chart where each manager has several direct reports and no loops is best modeled as a:','["truth table", "complete graph", "cycle graph", "tree"]'::jsonb,3,'A tree is a connected graph with no cycles.','original'),
('127.686.d.1.C',3,'A fair six-sided die is rolled once. The probability of rolling an even number is:','["1/2", "1/3", "1/6", "2/3"]'::jsonb,0,'Three of six outcomes are even.','original'),
('127.686.d.1.C',4,'A fair die is rolled. The expected value of the number shown is:','["6", "3.5", "4", "3"]'::jsonb,1,'(1+2+3+4+5+6)/6 = 3.5.','original'),
('127.686.d.2.A',3,'''It is raining or it is snowing'' becomes which propositional form if P = raining and Q = snowing?','["P ∧ Q", "P → Q", "P ∨ Q", "¬P"]'::jsonb,2,'''Or'' translates to disjunction.','original'),
('127.686.d.2.A',4,'''If I finish homework, then I can play'' with P = finish homework and Q = play is written:','["P ∨ Q", "Q → ¬P", "P ∧ ¬Q", "P → Q"]'::jsonb,3,'''If…then'' is implication.','original'),
('127.686.d.2.B',3,'In discrete math, a function from set A to set B assigns each element of A:','["exactly one element of B", "no elements of B", "two elements of A", "every element of B"]'::jsonb,0,'A function is single-valued.','original'),
('127.686.d.2.B',4,'A relation on a set differs from a function in that a relation may:','["never be written as ordered pairs", "pair one input with several outputs", "have no inputs", "use only numbers"]'::jsonb,1,'Relations are any sets of ordered pairs.','original'),
('127.686.d.2.C',3,'The Master theorem is used to solve:','["graph coloring puzzles", "truth tables", "divide-and-conquer recurrences like T(n)=aT(n/b)+f(n)", "modular clock problems only"]'::jsonb,2,'It gives running time of divide-and-conquer algorithms.','original'),
('127.686.d.2.C',4,'Merge sort has T(n)=2T(n/2)+n. By the Master theorem its time is:','["Θ(log n)", "Θ(n)", "Θ(n²)", "Θ(n log n)"]'::jsonb,3,'a=2, b=2, f(n)=n gives case 2: Θ(n log n).','original'),
('127.686.d.2.D',3,'A tool says a schedule graph needs 4 colors. In context, the number of colors means:','["the number of time slots needed so no conflicts overlap", "the number of bugs", "the number of students", "the file size"]'::jsonb,0,'Colors represent separate time slots.','original'),
('127.686.d.2.D',4,'In a social-network graph, a vertex with degree 120 means that person:','["posted 120 times", "is directly linked to 120 others", "is 120 years old", "has 120 messages unread"]'::jsonb,1,'Degree counts incident edges.','original'),
('127.686.d.2.E',3,'In set terms, A ∩ B means the elements that are:','["in the second set only", "in the first set only", "in each of the two sets at once", "in exactly one of the two sets"]'::jsonb,2,'Intersection means both sets.','original'),
('127.686.d.2.E',4,'The union of {1,2,3} and {3,4} is:','["{1,2,3,3,4}", "{3}", "{1,2,4}", "{1,2,3,4}"]'::jsonb,3,'Union combines elements without repeats.','original'),
('127.686.d.2.F',3,'Two statements that always have the same truth value are called:','["logically equivalent", "contradictions", "tautologies only", "contingent"]'::jsonb,0,'Equivalent statements match on every row of a truth table.','original'),
('127.686.d.2.F',4,'An argument is valid when:','["the conclusion is surprising", "the conclusion must be true whenever all premises are true", "the premises are false", "it has two premises"]'::jsonb,1,'Validity concerns structure, not truth of the premises.','original'),
('127.686.d.3.A',3,'In a truth table, P ∧ Q is true only when:','["either P or Q is true", "both are false", "both P and Q are true", "P is false"]'::jsonb,2,'Conjunction needs both.','original'),
('127.686.d.3.A',4,'The implication P → Q is false only when:','["P is false and Q is true", "both are true", "both are false", "P is true and Q is false"]'::jsonb,3,'A true premise leading to a false conclusion breaks the implication.','original'),
('127.686.d.3.B',3,'Two propositions whose truth-table columns match on every row are:','["equivalent", "contradictory", "unrelated", "undefined"]'::jsonb,0,'Identical columns show equivalence.','original'),
('127.686.d.3.B',4,'A truth table for (P ∨ ¬P) shows every row true, so the statement is a:','["predicate", "tautology", "contingency", "contradiction"]'::jsonb,1,'Always true means tautology.','original'),
('127.686.d.4.A',3,'A school database lists which student is in which club. This is best modeled with a:','["single integer", "loop counter", "relation between students and clubs", "password"]'::jsonb,2,'A relation pairs students with clubs.','original'),
('127.686.d.4.A',4,'Assigning each student ID to exactly one locker is best modeled as a:','["set of lockers only", "relation allowing many lockers per ID", "tree", "function from IDs to lockers"]'::jsonb,3,'Each input gets exactly one output.','original'),
('127.686.d.4.B',3,'A statement that is false on every row of its truth table is a:','["contradiction", "theorem", "tautology", "contingency"]'::jsonb,0,'Always false means contradiction.','original'),
('127.686.d.4.B',4,'A statement true on some rows and false on others is called a:','["tautology", "contingency", "axiom", "contradiction"]'::jsonb,1,'Its truth depends on the inputs.','original'),
('127.686.d.4.C',3,'The contrapositive of ''if it rains, the game is canceled'' is:','["if it rains, the game is played", "if the game is canceled, it rained", "if the game is not canceled, it did not rain", "if it does not rain, the game is not canceled"]'::jsonb,2,'Contrapositive negates and swaps: ¬Q → ¬P.','original'),
('127.686.d.4.C',4,'To disprove ''every prime number is odd'' you give a counterexample such as:','["7", "5", "3", "2"]'::jsonb,3,'2 is prime and even.','original'),
('127.686.d.4.D',3,'Predicate logic can say ''for every student x, x has an ID,'' which propositional logic cannot easily express because it lacks:','["quantifiers", "truth values", "negation", "variables of any kind"]'::jsonb,0,'Quantifiers like ∀ and ∃ extend propositional logic.','original'),
('127.686.d.4.D',4,'A limitation of predicate logic reasoning is that, unlike a truth table, checking validity in general is:','["always trivial", "undecidable by any single algorithm", "impossible to write down", "limited to two variables"]'::jsonb,1,'First-order validity is only semi-decidable.','original'),
('127.686.d.4.E',3,'Applying De Morgan''s law, ¬(P ∧ Q) is equivalent to:','["¬P → Q", "P ∨ Q", "¬P ∨ ¬Q", "¬P ∧ ¬Q"]'::jsonb,2,'Negating a conjunction flips to a disjunction of negations.','original'),
('127.686.d.4.E',4,'Using modus ponens, from ''P → Q'' and ''P'' you may conclude:','["¬P", "P → ¬Q", "¬Q", "Q"]'::jsonb,3,'Modus ponens affirms the antecedent.','original'),
('127.686.d.4.F',3,'A proof that a loop terminates uses logical reasoning to show:','["the loop condition eventually becomes false", "the code is short", "the variable is a string", "the loop is fast"]'::jsonb,0,'Termination proofs show the stopping condition is reached.','original'),
('127.686.d.4.F',4,'A rule of inference lets a prover:','["change the problem", "derive a new true statement from earlier true ones", "delete a premise", "guess a conclusion"]'::jsonb,1,'Inference rules preserve truth.','original'),
('127.686.d.4.G',3,'A direct proof of ''if n is even, then n² is even'' starts by:','["testing n = 2 only", "assuming the conclusion is false", "assuming n is even and showing n² is even", "assuming n² is odd"]'::jsonb,2,'Direct proofs go from hypothesis to conclusion.','original'),
('127.686.d.4.G',4,'A proof by contradiction begins by assuming:','["a smaller case is true", "the statement is true", "the premises are false", "the statement to be proved is false"]'::jsonb,3,'A contradiction then shows the assumption impossible.','original'),
('127.686.d.4.H',3,'Proving ''if n² is even then n is even'' is easiest by assuming n is odd. This is a:','["proof by contraposition", "direct proof", "induction", "proof by cases"]'::jsonb,0,'Assuming ¬Q and deriving ¬P is contrapositive.','original'),
('127.686.d.4.H',4,'Showing ''the square root of 2 is irrational'' is classically done by:','["a truth table", "contradiction", "counting arguments", "brute-force checking"]'::jsonb,1,'Assume rational, then derive an impossibility.','original'),
('127.686.d.4.I',3,'A recursive function calls itself on a smaller input, and induction proves it correct by showing the:','["output is a string", "largest input only", "base case and the step from k to k+1", "code compiles"]'::jsonb,2,'Induction mirrors recursion''s base and recursive steps.','original'),
('127.686.d.4.I',4,'A recursively defined list like f(0)=1, f(n)=2·f(n−1) is naturally verified using:','["a Venn diagram", "a pigeonhole argument", "random sampling", "mathematical induction"]'::jsonb,3,'Recursion and induction are closely linked.','original'),
('127.686.d.4.J',3,'Strong induction differs from weak induction in that the inductive step may assume:','["all earlier cases are true", "only the base case", "only the next case", "no cases"]'::jsonb,0,'Strong induction assumes P(1)…P(k).','original'),
('127.686.d.4.J',4,'Structural induction is the best fit for proving a property of:','["hardware speeds", "recursively defined trees or expressions", "random samples", "decimal numbers only"]'::jsonb,1,'It follows the recursive construction rules of a structure.','original'),
('127.686.d.4.K',3,'Flipping a coin twice, the second flip''s outcome is:','["impossible to predict", "always the same as the first", "independent of the first", "dependent on the first"]'::jsonb,2,'Coin flips do not affect each other.','original'),
('127.686.d.4.K',4,'Drawing two cards from a deck without replacing the first makes the draws:','["independent events", "impossible events", "certain events", "dependent events"]'::jsonb,3,'The first draw changes the second''s probabilities.','original'),
('127.686.d.4.L',3,'A program''s time satisfies T(n)=T(n−1)+1 with T(1)=1. T(5) equals:','["5", "6", "4", "10"]'::jsonb,0,'Each step adds 1: 1,2,3,4,5.','original'),
('127.686.d.4.L',4,'The recurrence T(n)=2T(n−1)+1 with T(1)=1 gives T(4)=','["8", "15", "10", "16"]'::jsonb,1,'1, 3, 7, 15.','original'),
('127.686.d.4.M',3,'An algorithm tries every ordering of 4 items. The number of orderings it must check is:','["12", "16", "24", "4"]'::jsonb,2,'4! = 24.','original'),
('127.686.d.4.M',4,'A lock code uses 3 digits (0–9), repeats allowed. The number of possible codes is:','["100", "720", "27", "1000"]'::jsonb,3,'10×10×10 = 1000.','original'),
('127.686.d.4.N',3,'A bag has 3 red and 2 blue marbles. The probability of picking blue is:','["2/5", "2/3", "1/2", "3/5"]'::jsonb,0,'Two of five marbles are blue.','original'),
('127.686.d.4.N',4,'A fair coin is flipped 3 times. The probability of getting exactly 2 heads is:','["1/4", "3/8", "1/2", "1/8"]'::jsonb,1,'C(3,2)/8 = 3/8.','original'),
('127.686.d.4.O',3,'A simple graph differs from a multigraph because a simple graph has:','["directed edges only", "only one vertex", "no parallel edges and no loops", "no vertices"]'::jsonb,2,'Multigraphs allow repeated edges.','original'),
('127.686.d.4.O',4,'A road network with one-way streets should be modeled as a:','["tree only", "simple set", "undirected graph", "directed graph"]'::jsonb,3,'Edges have direction.','original'),
('127.686.d.5.A',3,'Using a photo from another creator in a class project is ethical when you:','["have permission or a license and give credit", "remove the creator''s name", "assume anything online is free", "crop out the watermark"]'::jsonb,0,'Ethical use respects rights.','original'),
('127.686.d.5.A',4,'Copying a classmate''s proof and submitting it as yours is:','["collaboration", "plagiarism", "citation", "peer review"]'::jsonb,1,'Presenting others'' work as your own is plagiarism.','original'),
('127.686.d.5.B',3,'Proper digital etiquette in a class forum includes:','["posting in all capitals", "sharing passwords", "staying respectful and on topic", "replying with insults"]'::jsonb,2,'Etiquette keeps discussions productive.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_87_v1'
from (values
('127.686.d.5.B',4,'Installing licensed software on one computer and then copying it to many without permission violates:','["a file name rule", "a font rule", "a color rule", "the software license"]'::jsonb,3,'Licenses limit how many installs are allowed.','original'),
('127.686.d.5.C',3,'Graph theory helps a delivery company by:','["finding short routes between stops", "printing labels", "adding colors", "sorting fonts"]'::jsonb,0,'Shortest-path ideas come from graphs.','original'),
('127.686.d.5.C',4,'Counting techniques such as combinations help a password security analyst estimate:','["monitor brightness", "how many possible passwords an attacker must try", "internet cost", "keyboard layout"]'::jsonb,1,'More possible passwords means more attacks needed.','original'),
('127.686.d.6.A',3,'If A={1,2,3} and B={3,4}, then A∪B has how many elements?','["5", "2", "4", "3"]'::jsonb,2,'{1,2,3,4} has 4 elements.','original'),
('127.686.d.6.A',4,'If A={1,2,3,4} and B={2,4,6}, then A−B is:','["{1,2,3,4,6}", "{2,4}", "{6}", "{1,3}"]'::jsonb,3,'A−B keeps elements in A not in B.','original'),
('127.686.d.6.B',3,'Eleven people share birthdays across 10 months. By the pigeonhole principle, at least two share:','["a birth month", "a birth year", "a height", "a first name"]'::jsonb,0,'More items than boxes forces a repeat.','original'),
('127.686.d.6.B',4,'The cardinality of the set {a, b, {c, d}} is:','["2", "3", "4", "5"]'::jsonb,1,'The set holds three elements; one is itself a set.','original'),
('127.686.d.6.C',3,'In most logic systems, which operator is evaluated first in P ∨ ¬Q?','["∨", "none of them", "¬", "P"]'::jsonb,2,'Negation has the highest precedence.','original'),
('127.686.d.6.C',4,'With standard precedence, P ∨ Q ∧ R is read as:','["P ∧ (Q ∨ R)", "(P ∨ Q) ∨ R", "(P ∨ Q) ∧ R", "P ∨ (Q ∧ R)"]'::jsonb,3,'AND binds tighter than OR.','original'),
('127.686.d.6.D',3,'De Morgan''s law says ¬(P ∨ Q) is the same as:','["¬P ∧ ¬Q", "P ∧ Q", "P → Q", "¬P ∨ ¬Q"]'::jsonb,0,'Negating OR gives AND of negations.','original'),
('127.686.d.6.D',4,'To show P → Q is equivalent to ¬P ∨ Q, a student can:','["count variables", "compare their truth tables", "factor an integer", "draw a tree"]'::jsonb,1,'Matching truth tables prove equivalence.','original'),
('127.686.d.6.E',3,'The symbol ∃ in predicate logic means:','["for all", "implies", "there exists", "not"]'::jsonb,2,'∃ is the existential quantifier.','original'),
('127.686.d.6.E',4,'''Every student has a locker'' is best written with the quantifier:','["↔", "¬", "∃", "∀"]'::jsonb,3,'∀ is the universal quantifier.','original'),
('127.686.d.6.F',3,'A proof of algorithm complexity shows how an algorithm''s work:','["grows as the input grows", "is colored", "looks on screen", "is named"]'::jsonb,0,'Complexity proofs bound growth.','original'),
('127.686.d.6.F',4,'A loop invariant is used in a proof to show:','["the loop never runs", "a condition stays true each time through the loop", "the variable is private", "the code is short"]'::jsonb,1,'Invariants support correctness proofs.','original'),
('127.686.d.6.G',3,'A shirt comes in 4 colors and 3 sizes. By the product rule, the number of kinds is:','["7", "9", "12", "16"]'::jsonb,2,'4×3 = 12.','original'),
('127.686.d.6.G',4,'You can take a bus (5 routes) or a train (3 routes) but not both. By the sum rule, the choices total:','["15", "53", "2", "8"]'::jsonb,3,'5+3 = 8.','original'),
('127.686.d.6.H',3,'The number of ways to arrange 3 different books on a shelf is:','["6", "9", "3", "27"]'::jsonb,0,'3! = 6.','original'),
('127.686.d.6.H',4,'Choosing 2 team captains from 5 players, order not mattering, can be done in:','["25 ways", "10 ways", "5 ways", "20 ways"]'::jsonb,1,'C(5,2) = 10.','original'),
('127.686.d.6.I',3,'If a(1)=3 and a(n)=a(n−1)+2, then a(4) is:','["7", "11", "9", "5"]'::jsonb,2,'3, 5, 7, 9.','original'),
('127.686.d.6.I',4,'If a(1)=1 and a(n)=3·a(n−1), then a(4) is:','["12", "81", "9", "27"]'::jsonb,3,'1, 3, 9, 27.','original'),
('127.686.d.6.J',3,'The binomial theorem expands (x + y)² as:','["x² + 2xy + y²", "x² + y²", "x² − y²", "2x + 2y"]'::jsonb,0,'Coefficients come from the binomial row 1 2 1.','original'),
('127.686.d.6.J',4,'How many ways can exactly 2 successes occur in 4 independent trials (count only)?','["12", "6", "8", "4"]'::jsonb,1,'C(4,2) = 6.','original'),
('127.686.d.6.K',3,'Bayes'' theorem is used to:','["compress a file", "draw a graph", "update a probability after new evidence", "sort a list"]'::jsonb,2,'It reverses conditional probabilities.','original'),
('127.686.d.6.K',4,'A spam filter flags words and then uses Bayes'' theorem to estimate:','["the sender''s age", "the message length in bytes", "the server speed", "the chance a message is spam given its words"]'::jsonb,3,'It computes P(spam | words).','original'),
('127.686.d.6.L',3,'A traversal that visits a tree''s left subtree, then the node, then the right subtree is called:','["in-order", "pre-order", "level-order", "post-order"]'::jsonb,0,'Left, node, right is in-order.','original'),
('127.686.d.6.L',4,'A traversal that explores a graph by visiting all neighbors before moving deeper is:','["hash search", "breadth-first search", "binary search", "depth-first search"]'::jsonb,1,'BFS expands level by level.','original'),
('127.686.d.6.M',3,'Which data structure naturally stores a family tree?','["a single integer", "a bit flag", "a tree", "a stack of numbers"]'::jsonb,2,'Parent–child relationships form a tree.','original'),
('127.686.d.6.M',4,'A graph stored as a list of each vertex''s neighbors is called an:','["binary heap", "hash digest", "index card", "adjacency list"]'::jsonb,3,'Adjacency lists are compact for sparse graphs.','original'),
('127.687.d.1.A',3,'The story, characters and goals a designer writes for a game form its:','["narrative and concept", "power supply", "file format", "network speed"]'::jsonb,0,'Storyline and concepts shape design.','original'),
('127.687.d.1.A',4,'A designer who decides the player must rescue a lost robot across three worlds is working on the game''s:','["server cost", "storyline and objectives", "audio compression", "memory limits"]'::jsonb,1,'Objectives and story are core design elements.','original'),
('127.687.d.1.B',3,'A design concept document for a game is used to:','["install the game", "sell the console", "describe the game idea, rules and goals for the team", "test the sound card"]'::jsonb,2,'It communicates the plan.','original'),
('127.687.d.1.B',4,'A concept document usually includes the game''s genre, target players and:','["wiring diagrams", "the printer model", "student passwords", "core gameplay and goals"]'::jsonb,3,'Core play and goals define the game.','original'),
('127.687.d.1.C',3,'A game storyboard shows:','["key scenes or screens in order, like a comic strip", "the final source code", "the file sizes", "the sales numbers"]'::jsonb,0,'Storyboards plan visual flow.','original'),
('127.687.d.1.C',4,'A storyboard helps a team catch a confusing level layout:','["never", "before any expensive coding is done", "only by testing audio", "after launch only"]'::jsonb,1,'Drawing first is cheap to change.','original'),
('127.687.d.1.D',3,'The overall ''look'' of a game''s art, such as pixel art or cartoon, is its:','["frame loop", "port number", "art style", "compiler"]'::jsonb,2,'Style sets a consistent look.','original'),
('127.687.d.1.D',4,'Keeping a character''s colors and proportions the same across all levels shows a focus on:','["audio mixing", "server load", "file naming only", "visual consistency"]'::jsonb,3,'Consistency makes art feel unified.','original'),
('127.687.d.1.E',3,'A bitmap image is made of:','["a grid of colored pixels", "text characters only", "mathematical curves", "sound waves"]'::jsonb,0,'Bitmaps store pixels.','original'),
('127.687.d.1.E',4,'Enlarging a small bitmap sprite a lot usually makes it look:','["sharper", "blocky or blurry", "smaller", "louder"]'::jsonb,1,'Bitmaps lose clarity when scaled up.','original'),
('127.687.d.1.F',3,'A tiled background repeats one small image to cover a larger area. This saves:','["player names", "story ideas", "memory and drawing effort", "sound files"]'::jsonb,2,'One tile can fill the screen.','original'),
('127.687.d.1.F',4,'A solid-color background differs from an image background because it:','["needs a sprite sheet", "must be animated", "requires audio", "uses a single fill color with no picture"]'::jsonb,3,'A solid background is one color.','original'),
('127.687.d.1.G',3,'To draw a rectangle in code, a program typically needs its position and:','["width and height", "a password", "a file extension", "a song title"]'::jsonb,0,'Rectangles need size and location.','original'),
('127.687.d.1.G',4,'A circle is usually drawn from a center point and a:','["soundtrack", "radius", "hash", "tile map"]'::jsonb,1,'Center and radius define a circle.','original'),
('127.687.d.1.H',3,'A sprite in a game is:','["a rule document", "a type of loop", "a 2D image or animation that represents an object", "a server"]'::jsonb,2,'Sprites are movable game images.','original'),
('127.687.d.1.H',4,'To make a sprite walk, a developer changes its position and also:','["changes the story", "deletes its image", "raises the volume", "swaps its animation frames"]'::jsonb,3,'Frame changes create motion.','original'),
('127.687.d.1.I',3,'A sprite sheet is one image that holds:','["many frames of a character''s animation", "only background music", "the game''s source code", "the player''s score"]'::jsonb,0,'Sheets pack frames together.','original'),
('127.687.d.1.I',4,'Using a sprite sheet instead of many separate image files usually:','["prevents scaling", "reduces loading overhead", "raises memory errors", "removes animation"]'::jsonb,1,'One file loads faster than many.','original'),
('127.687.d.1.J',3,'Transparency in a sprite lets the:','["code run faster", "sprite play sound", "background show through parts of the image", "screen go dark"]'::jsonb,2,'Transparent pixels reveal what''s behind.','original'),
('127.687.d.1.J',4,'The number of times per second a game redraws its screen is its:','["bit depth", "port", "file path", "refresh rate (frame rate)"]'::jsonb,3,'Refresh rate measures redraws per second.','original'),
('127.687.d.1.K',3,'A short sound played when a player collects a coin is a:','["sound effect", "texture", "variable", "tile"]'::jsonb,0,'Effects give action feedback.','original'),
('127.687.d.1.K',4,'Editing a sound file to remove silence at the start helps a game by:','["saving a sprite", "making the sound play at the right moment", "creating a level", "adding colors"]'::jsonb,1,'Silence causes audible delay.','original'),
('127.687.d.1.L',3,'Looping background music means it:','["is deleted", "never starts", "repeats continuously", "plays only once"]'::jsonb,2,'Looping restarts the track.','original'),
('127.687.d.1.L',4,'A pause button in a game should also:','["delete the save file", "reset the level", "increase the score", "pause or lower the game audio"]'::jsonb,3,'Pausing audio matches the paused state.','original'),
('127.687.d.2.A',3,'Setting deadlines for art, code and testing and checking them weekly is:','["project timeline tracking", "pixel counting", "audio looping", "sprite editing"]'::jsonb,0,'Timelines keep a project on schedule.','original'),
('127.687.d.2.A',4,'A team that finds its level design is two weeks behind should:','["delete the level", "adjust the schedule or scope and tell the team", "hide the delay", "stop testing"]'::jsonb,1,'Tracking exists to guide adjustments.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
