insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_87_v1'
from (values
('127.687.d.2.B',3,'Asking classmates to play a prototype and tell you what confused them is:','["writing a license", "compressing audio", "gathering peer feedback", "debugging a sprite"]'::jsonb,2,'Feedback shows problems you missed.','original'),
('127.687.d.2.B',4,'When five testers all get stuck at the same jump, the designer should:','["remove the sound", "blame the testers", "ignore it", "redesign that part of the level"]'::jsonb,3,'Repeated problems signal a design flaw.','original'),
('127.687.d.2.C',3,'A game developer uses an integrated development environment (IDE) mainly to:','["write, run and debug code in one place", "browse social media", "print posters", "record voice calls"]'::jsonb,0,'IDEs bundle coding tools.','original'),
('127.687.d.2.C',4,'Version control software helps a game team by:','["raising the frame rate", "tracking changes and letting members merge work safely", "creating sprites automatically", "compressing music"]'::jsonb,1,'It records history and avoids overwrites.','original'),
('127.687.d.2.D',3,'Using a school network to find a free-to-use sound library is an example of:','["drawing a storyboard", "editing sprites", "using network resources to acquire information", "coding a loop"]'::jsonb,2,'Networks give access to resources.','original'),
('127.687.d.2.D',4,'A team keeps assets in labeled folders on a shared drive to:','["hide files from teammates", "avoid backups", "increase file size", "organize and maintain files so anyone can find them"]'::jsonb,3,'Good organization saves time.','original'),
('127.687.d.2.E',3,'In the game business, a publisher typically:','["funds, markets and distributes games", "plays testers'' games", "draws every sprite", "writes every line of code"]'::jsonb,0,'Publishers handle money and distribution.','original'),
('127.687.d.2.E',4,'A small team that designs and programs its own game and sells it directly is an:','["retailer only", "independent (indie) developer", "console maker", "publisher only"]'::jsonb,1,'Indies create and often self-publish.','original'),
('127.687.d.2.F',3,'Playing with friends over the internet in the same game world is called:','["a screensaver", "offline solitaire", "online multiplayer", "a spreadsheet"]'::jsonb,2,'Online play connects players over a network.','original'),
('127.687.d.2.F',4,'One challenge of online games compared to offline ones is:','["no sound", "no graphics", "no rules", "lag caused by network delay"]'::jsonb,3,'Latency affects online play.','original'),
('127.687.d.3.A',3,'Watching people play a board game and noting what slows them down is:','["collecting game play data", "compiling code", "editing audio", "drawing sprites"]'::jsonb,0,'Observation is research.','original'),
('127.687.d.3.A',4,'Timing how long each turn takes in a board game helps a designer see:','["how loud to be", "where the pacing drags", "which console to use", "what font to use"]'::jsonb,1,'Turn times reveal pacing issues.','original'),
('127.687.d.3.B',3,'Playability describes how easy and enjoyable a game is to:','["advertise", "store", "learn and play", "download"]'::jsonb,2,'Playability measures player experience.','original'),
('127.687.d.3.B',4,'A tester writes down that the tutorial confuses new players. This note is:','["a sprite sheet", "a license", "a loop", "documentation of a playability issue"]'::jsonb,3,'Documented findings guide revisions.','original'),
('127.687.d.3.C',3,'Different players enjoy different things, such as winning, exploring or socializing. These are called:','["player types", "loop types", "file types", "data types"]'::jsonb,0,'Player types describe motivations.','original'),
('127.687.d.3.C',4,'A game with big maps and hidden secrets mostly appeals to which kind of player?','["none", "explorers", "speedrunners only", "spectators only"]'::jsonb,1,'Explorers enjoy discovery.','original'),
('127.687.d.4.A',3,'The game design process often begins with:','["shipping the disc", "locking the code", "generating and sorting ideas", "selling the game"]'::jsonb,2,'Ideas come first, then prototypes.','original'),
('127.687.d.4.A',4,'After choosing an idea, a designer commonly builds a quick:','["box design", "final soundtrack", "marketing poster", "prototype to test the core mechanic"]'::jsonb,3,'Prototypes test ideas early.','original'),
('127.687.d.4.B',3,'A variable that stores a player''s score as a whole number uses the data type:','["integer", "boolean", "string", "image"]'::jsonb,0,'Whole numbers are integers.','original'),
('127.687.d.4.B',4,'A variable that is either true or false, such as isGameOver, has the type:','["array", "boolean", "string", "float"]'::jsonb,1,'Booleans hold true/false.','original'),
('127.687.d.4.C',3,'Good game instructions should be:','["hidden in code", "written in a rare language", "clear and short enough to follow quickly", "secret"]'::jsonb,2,'Players need understandable rules.','original'),
('127.687.d.4.C',4,'If playtesters keep misreading the rules, the rules probably need to be:','["printed smaller", "made longer and vaguer", "removed entirely", "reworded or illustrated"]'::jsonb,3,'Revise unclear rules.','original'),
('127.687.d.4.D',3,'The user experience of a game is how it feels to the:','["person playing it", "server", "publisher''s accountant", "compiler"]'::jsonb,0,'UX is the player''s experience.','original'),
('127.687.d.4.D',4,'If the rules say ''press A to jump'' but the game uses the space bar, the mismatch hurts:','["the frame rate", "the user experience", "the sprite colors", "the file size"]'::jsonb,1,'Rules and controls must agree.','original'),
('127.687.d.4.E',3,'Writing game rules that a new player can follow without help requires:','["long essays", "advanced jargon", "simple, step-by-step wording", "random order"]'::jsonb,2,'Simple steps aid understanding.','original'),
('127.687.d.4.E',4,'Rules that list the goal, how to move and how to win or lose are:','["debug logs", "art notes", "unfinished rules", "complete rules"]'::jsonb,3,'Good rules cover goal, actions and outcomes.','original'),
('127.687.d.4.F',3,'Game software is built by combining code, art, audio and:','["game rules and logic", "email", "printer drivers", "spreadsheets"]'::jsonb,0,'Logic ties the assets together.','original'),
('127.687.d.4.F',4,'Developing in small working pieces and testing each is called:','["one-shot printing", "iterative development", "random coding", "cold storage"]'::jsonb,1,'Iteration finds problems early.','original'),
('127.687.d.4.G',3,'A bug where the player falls through the floor is a game:','["feature", "theme", "defect", "sprite"]'::jsonb,2,'Defects are unintended faults.','original'),
('127.687.d.4.G',4,'After fixing a defect, a developer should:','["skip testing", "hide the bug", "delete the test", "retest to be sure it is fixed and nothing else broke"]'::jsonb,3,'Verification prevents regressions.','original'),
('127.687.d.4.H',3,'Testing a game in a planned, repeatable way is:','["sound testing practice", "luck", "avoidance", "guesswork"]'::jsonb,0,'Planned tests find more faults.','original'),
('127.687.d.4.H',4,'Playing only the easy first level before release is poor testing because it:','["finds all bugs", "misses problems in harder or later parts", "is too thorough", "tests everything"]'::jsonb,1,'Coverage matters.','original'),
('127.687.d.5.A',3,'Copyright law protects a game''s art, code and music from:','["being reviewed", "being played", "being copied without permission", "being sold legally"]'::jsonb,2,'Copyright limits unauthorized copying.','original'),
('127.687.d.5.A',4,'A player''s data like a username and email in a game raises concerns about:','["level design", "art style", "frame rate", "privacy"]'::jsonb,3,'Personal data needs protection.','original'),
('127.687.d.5.B',3,'Using an artist''s character in your game ethically requires:','["permission or a license", "hiding the source", "a new name only", "a lower price"]'::jsonb,0,'Respect others'' creations.','original'),
('127.687.d.5.B',4,'Using free, openly licensed music in a game is ethical when you:','["ignore the terms", "follow the license terms, such as crediting the author", "claim you wrote it", "resell the track"]'::jsonb,1,'Licenses set conditions.','original'),
('127.687.d.5.C',3,'Proper digital etiquette in an online game chat means:','["insulting teammates", "sharing passwords", "treating other players respectfully", "spamming"]'::jsonb,2,'Etiquette keeps spaces safe.','original'),
('127.687.d.5.C',4,'An acceptable use policy at school says that game devices should be used:','["to bypass filters", "any way you like", "to harass others", "only as the policy allows"]'::jsonb,3,'AUPs set rules.','original'),
('127.687.d.5.D',3,'Morphing or editing a copyrighted picture does not by itself:','["remove the original owner''s rights", "change the file type", "shrink it", "make it brighter"]'::jsonb,0,'Altering doesn''t erase copyright.','original'),
('127.687.d.5.D',4,'To safely include a recognizable character''s image in a school project, a student should:','["change one color only", "get permission or use original art", "copy it silently", "trace it closely and say it is original"]'::jsonb,1,'Original or permitted art is safe.','original'),
('127.687.d.5.E',3,'One social issue discussed about gaming is:','["the color red", "font choice", "how much time players spend playing", "tile sizes"]'::jsonb,2,'Screen time is a common concern.','original'),
('127.687.d.5.E',4,'A positive social effect of gaming can be:','["isolation guaranteed", "no effect ever", "lower grades guaranteed", "teamwork and problem-solving skills"]'::jsonb,3,'Games can build collaboration.','original'),
('127.687.d.5.F',3,'A game set in ancient Egypt should be designed with:','["respect for the culture it portrays", "mocking stereotypes", "no research", "random symbols"]'::jsonb,0,'Cultural accuracy shows care.','original'),
('127.687.d.5.F',4,'Designers consult cultural advisers so their game avoids:','["all colors", "harmful stereotypes and errors", "all sprites", "all audio"]'::jsonb,1,'Advisers help portray cultures fairly.','original'),
('127.687.d.6.A',3,'The part of a game that runs the main loop, draws graphics and handles input is the:','["sprite sheet", "rule book", "game engine", "storyboard"]'::jsonb,2,'Engines provide core systems.','original'),
('127.687.d.6.A',4,'Game play subsystems include things like physics, input handling and:','["accounting", "tax filing", "email", "rendering"]'::jsonb,3,'Rendering draws the scene.','original'),
('127.687.d.6.B',3,'A game uses a random number to decide which enemy appears. Using it makes play:','["less predictable", "identical each time", "impossible", "silent"]'::jsonb,0,'Randomness adds variety.','original'),
('127.687.d.6.B',4,'To roll a die from 1 to 6 with a function that returns 0–5, you can:','["subtract 1", "add 1 to the result", "double it", "square it"]'::jsonb,1,'Shifts 0–5 to 1–6.','original'),
('127.687.d.6.C',3,'A conditional statement lets a game:','["run forever", "draw sprites only", "do something only if a condition is true", "play music only"]'::jsonb,2,'Conditionals branch logic.','original'),
('127.687.d.6.C',4,'Code that says ''if lives == 0, show Game Over'' is an example of a:','["array", "class", "loop", "conditional"]'::jsonb,3,'It acts only when a condition holds.','original'),
('127.687.d.6.D',3,'A data model for a game player might store name, health and:','["inventory", "the weather", "the printer", "wallpaper"]'::jsonb,0,'The model holds the player''s data.','original'),
('127.687.d.6.D',4,'Keeping player data in one organized structure makes it easier to:','["duplicate bugs", "save, load and update", "hide it", "lose it"]'::jsonb,1,'Good models simplify handling.','original'),
('127.687.d.6.E',3,'In object-oriented game programming, a class is like a:','["speaker", "screen", "blueprint for creating game objects", "cable"]'::jsonb,2,'Classes define object templates.','original'),
('127.687.d.6.E',4,'If Enemy is a class, then each individual goblin in the game is:','["a class", "a file", "a loop", "an object (instance)"]'::jsonb,3,'Instances come from classes.','original'),
('127.687.d.6.F',3,'Event-driven programming means the program reacts to:','["things like key presses and clicks", "only the clock", "only code comments", "nothing"]'::jsonb,0,'Events trigger responses.','original')
